insert into public.routes (slug, name, name_en, region_id, difficulty, days_min, days_max, duration_hours, distance_km, elevation_gain_m, elevation_loss_m, max_altitude_m, min_altitude_m, route_type, season_months, tags, summary, description, difficulty_notes, getting_there, accommodation, water, permits, dangers, mobile_coverage, gear, tips, start_name, start_lat, start_lng, end_name, end_lat, end_lng, featured, status, sources) values
('mleta-lomisa','მლეთა – ლომისის მონასტერი','Mleta – Lomisa monastery','mtiuleti','moderate',1,1,4,9,720,720,2200,1480,'out_and_back','{5,6,7,8,9,10}'::smallint[],array['history','views','pilgrimage']::text[],'ძველი სამლოცველო გზა მლეთიდან ლომისის წმ. გიორგის მონასტრამდე — ხედით არაგვის ხეობაზე და კავკასიონზე.','ქვემო მლეთის ძველი ლომისის ეკლესიიდან (1876 წ.) ბილიკი ციცაბო ფერდობზე ადის ლომისის მონასტრამდე (~2 200 მ). ლომისობაზე (აღდგომიდან მეშვიდე კვირის ოთხშაბათს) ათასობით მომლოცველი ამ გზით ადის, ზოგი ფეხშიშველიც. დანარჩენ დროს ბილიკი მშვიდია, ზემოდან კი თეთრი არაგვის ხეობა და გუდაურის მთები ჩანს.','~700 მ განუწყვეტელი, ციცაბო აღმართი, მაგრამ კარგი ბილიკი.','მლეთამდე თბილისიდან გუდაურის/სტეფანწმინდის მარშრუტკით (დიდუბიდან, ~2 სთ).',null,'წყალი თან წაიღე.','არ არის საჭირო.','მონასტრის უკან, ქსნის ხეობისკენ ნუ ჩახვალ — იქ ოკუპირებული ტერიტორიაა.','უმეტესად არის.',seed.gear(array['BOOTS','BACKPACK_DAY','WATER_2','RAIN','FLEECE','SUN','SNACKS','FIRST_AID','OFFLINE_MAP','POLES','HEADLAMP','TRASH']),array['ლომისობის დღეს ბილიკი ძალიან ხალხმრავალია — თუ სიმშვიდე გინდა, სხვა დღე აირჩიე.']::text[],'ქვემო მლეთა (ლომისის ეკლესია)',42.42941,44.50782,'ლომისის წმ. გიორგის მონასტერი',42.41194,44.4995,false,'published','https://georgia.travel/mleta-village-lomisa-church'),
('roshka-abudelauri-lakes','როშკა – აბუდელაურის ტბები','Roshka – Abudelauri lakes','khevsureti','moderate',1,1,5.5,16,820,820,2810,2000,'out_and_back','{6,7,8,9}'::smallint[],array['lakes','glacier','views','camping']::text[],'სამი ფერის ტბა ჭაუხის კედლის ძირში: მწვანე, ცისფერი და თეთრი — ხევსურეთის ყველაზე ლამაზი დღიური ლაშქრობა.','როშკიდან ბილიკი მდინარის გასწვრივ ადის ხეობაში და ჯერ მწვანე ტბასთან (~2 590 მ) მიდის, რომელიც ტყიან ფერდობს შორისაა. აქედან ბილიკი ცისფერ ტბამდე და შემდეგ თეთრ ტბამდე (~2 810 მ) გრძელდება — ეს უკანასკნელი მყინვარის ძირშია და ზაფხულშიც ცივი, რძისფერი წყალი აქვს. ზემოთ ჭაუხის დაკბილული კლდეები დგას.','ზომიერი აღმართი, მაგრამ თეთრ ტბასთან ბოლო ნაწილი ციცაბო და ქვიანია. ჯოხები და კარგი ფეხსაცმელი გამოგადგება.','როშკამდე თბილისიდან ~3–3.5 საათია მანქანით (ბოლო ნაწილი ცუდი გზაა). საზოგადოებრივი ტრანსპორტი თითქმის არ დადის — ტაქსი ან ტური. სიბნელეში ამ გზაზე ნუ იმგზავრებ.','როშკაში რამდენიმე საოჯახო სასტუმროა. ტბებთან კარვის დადგმა შეიძლება.','მდინარე და ნაკადულები მთელ გზაზეა — გაწმინდე.','არ არის საჭირო.','ზამთარში მიუწვდომელია. ზემო ნაწილში ციცაბო ნაყარი. ამინდი სწრაფად ფუჭდება.','როშკაში არის, ხეობაში — სუსტი.',seed.gear(array['BOOTS','BACKPACK_DAY','WATER_2','RAIN','FLEECE','SUN','SNACKS','FIRST_AID','OFFLINE_MAP','POLES','HEADLAMP','TRASH']),array['ღამე როშკაში გაატარე და ბილიკზე დილით ადრე გადი — ტბები ჯერ კიდევ სარკესავითაა.','ძლიერი მოლაშქრეებისთვის: ტბებიდან ჭაუხის უღელტეხილით შეგიძლია ჯუთაში გადახვიდე (იხ. ''ჯუთა – ჭაუხის უღელტეხილი – როშკა'').']::text[],'როშკა',42.54436,44.89838,'აბუდელაურის თეთრი ტბა',42.54604,44.82008,true,'published','https://wander-lush.org/day-hikes-near-tbilisi-georgia/ ; https://www.caucasus-trekking.com/treks/chaukhi'),
('shatili-mutso','შატილი – მუცო','Shatili – Mutso','khevsureti','easy',1,1,3.5,10,350,200,1700,1400,'one_way','{6,7,8,9,10}'::smallint[],array['history','towers','villages','views']::text[],'არღუნის ხეობით შატილის ციხე-სოფლიდან მუცოს კლდეზე შეფენილ ციხე-ქალაქამდე — ხევსურეთის ორი ყველაზე ცნობილი ძეგლი ერთ დღეში.','შატილის ციხე-სოფლიდან გზა არღუნის ხეობას აყვება სამხრეთით, ანდაქის შესართავისკენ, მიტოვებული სოფლების გავლით. ბოლო 20–30 წუთი ციცაბო ბილიკით ადიხარ მუცოს ციხე-ქალაქამდე, რომელიც კლდის თხემზეა აშენებული და ბოლო წლებში აღდგა.

დამატებით: შატილიდან საპირისპირო მიმართულებით, ჩრდილოეთით ~2.5 კმ-ში ანატორის შუასაუკუნეების აკლდამებია — ცალკე მოკლე გასეირნებაა.','ძირითადად გრუნტის გზა; ბოლოს მოკლე ციცაბო აღმართი.','შატილამდე თბილისიდან ~5 სთ-ია დათვისჯვრის უღელტეხილით (გზა ჩვეულებრივ ივნისიდან ოქტომბრამდე ღიაა). მარშრუტკა ზაფხულში კვირაში ორჯერ დადის — განრიგი დიდუბის სადგურზე გადაამოწმე. უკან მუცოდან ტაქსით ან იმავე გზით ფეხით.','შატილში — საოჯახო სასტუმროები (ზოგი ძველ კოშკებში). მუცოს ქვემოთ ბანაკის ადგილები.','მდინარე გვერდითაა, მაგრამ სასმელი წყალი წაიღე.','საშვი არ არის საჭირო, მაგრამ ჩეჩნეთის საზღვართან ახლოსაა — პასპორტი თან იქონიე.','აკლდამებში ძვლებს ხელს ნუ ახლებ. ციცაბო ბილიკი ციხისკენ წვიმაში მოლიპულია.','შატილში არის, ხეობაში — სუსტი.',seed.gear(array['SHOES_LIGHT','WATER_1','SUN','RAIN','SNACKS','FIRST_AID','TRASH','ID','BOOTS']),array['თუ მანქანა გყავს, მუცოს ძირამდე მიდიხარ და მხოლოდ ციხეზე ადიხარ — ეს 30 წუთია.']::text[],'შატილი',42.65879,45.1575,'მუცოს ციხე-ქალაქი',42.60743,45.20798,false,'published','https://eurasia.travel/?p=46173'),
('omalo-shatili-atsunta','ომალო – შატილი (აწუნთის უღელტეხილი)','Omalo to Shatili via Atsunta pass','tusheti','hard',4,5,null,75,2950,3580,3430,1400,'one_way','{7,8,9}'::smallint[],array['pass','villages','towers','river_crossing','border_zone','camping','huts','remote']::text[],'საქართველოს ერთ-ერთი ყველაზე ველური ტრეკი: თუშეთიდან ხევსურეთში ხუთ დღეში, 3 430 მ სიმაღლის აწუნთის უღელტეხილით.','ომალოდან პირიქითა ალაზნის ხეობით მიდიხარ თუშურ სოფლებზე — დართლო, ჭეშო, ფარსმა, გირევი. გირევის შემდეგ დასახლებები მთავრდება: ქვახიდის საძოვრები, ორჯერ მდინარის ფონით გადალახვა და აწუნთის უღელტეხილი (~3 430 მ), რომლის იქით არდოტის ხეობა და მუცოა. ბოლო დღე შატილში მთავრდება. ქვახიდზე და ხიდოთნის ქედზე სალაშქრო თავშესაფრებია, თუმცა კარავი სარეზერვოდ მაინც წაიღე.','ხუთი სრული დღე, მაღალი უღელტეხილი, მდინარის ფონით გადალახვა (წვიმის შემდეგ — წელამდე), მოშორებული ტერიტორია. შუა სეზონის გარეთ კიდევ უფრო რთულდება.','ომალომდე საზოგადოებრივი ტრანსპორტი არ დადის. თბილისიდან ქვემო ალვანამდე მარშრუტკით (~2 სთ), იქიდან 4x4 ჯიპით აბანოს უღელტეხილის გავლით (~4 სთ; 2026 წლის მონაცემით 100–120 ლარი ერთ მგზავრზე). გზა ჩვეულებრივ ივნისიდან ოქტომბრამდეა ღია და საქართველოს ერთ-ერთი ყველაზე სახიფათოა — მხოლოდ გამოცდილ ადგილობრივ მძღოლთან იარე. შატილიდან თბილისისკენ მარშრუტკა კვირაში ორჯერ (2026 წლის მონაცემით ხუთშაბათს და კვირას, 12:00) — ბილეთი წინასწარ დაჯავშნე.','დართლოში, გირევსა და შატილში საოჯახო სასტუმროები (ჩვეულებრივ კვებით). ქვახიდზე და ხიდოთნის ქედზე — სალაშქრო თავშესაფრები (ხალიჩა და საძილე ტომარა საჭიროა).','ნაკადულები ბევრია, თუმცა ხიდოთნის ქედზე ზაფხულის ბოლოს წყალი ცოტაა.','სასაზღვრო ზონაა: სასაზღვრო პოლიციის პუნქტებზე (გირევი და ხონისჭალა) პასპორტით რეგისტრაცია სავალდებულოა. ინფორმაცია: თუშეთის ეროვნული პარკის ადმინისტრაცია.','მდინარის ფონი ქვახიდის ხეობაში (გადადი დილით, ჯგუფით), მწყემსის ძაღლები, ჭექა-ქუხილი უღელტეხილზე. სეზონის დასაწყისში უღელტეხილზე ბევრი თოვლია — 2026 წელს, მაგალითად, ივლისის შუამდე გასავლელი არ იყო.','ომალოსა და შატილში არის; გირევის შემდეგ ორი დღე — თითქმის არ არის.',seed.gear(array['BOOTS','BACKPACK_CAMP','TENT','STOVE','FOOD_DAYS','RAIN','FLEECE','HAT_GLOVES','SUN','WATER_2','FILTER_REQ','FIRST_AID','OFFLINE_MAP','POLES_REQ','HEADLAMP','POWERBANK','CASH','TRASH','ID','SANDALS']),array['გასვლამდე ჰკითხე გირევის მესაზღვრეებს უღელტეხილის და მდინარის მდგომარეობა — ისინი ყოველდღიურ ინფორმაციას ფლობენ.','ცხენით ბარგის გადატანა შეიძლება გირევში ან ომალოში შეთანხმდე.','თუ დრო მოკლეა, ომალო – დართლო – გირევი თავისთავად ლამაზი 2–3 დღიანი ლაშქრობაა.']::text[],'ომალო',42.37092,45.63308,'შატილი',42.65879,45.1575,true,'published','https://caucasus-trekking.com/treks/omaloshatili'),
('omalo-dartlo-girevi','ომალო – დართლო – გირევი','Omalo – Dartlo – Girevi','tusheti','easy',2,2,null,25,820,870,2200,1750,'one_way','{6,7,8,9}'::smallint[],array['villages','towers','history','guesthouses','family']::text[],'თუშეთის ყველაზე ლამაზი სოფლები ორ მარტივ დღეში: ომალოს ციხე, დართლოს კოშკები, კვავლო, ჭეშო, ფარსმა და გირევი.','პირველი დღე ომალოდან დართლომდე მიდის — სოფლამდე, რომელიც ქვის კოშკებითა და სახლებით ხეობის ფერდზეა შეფენილი. მეორე დღეს პირიქითა ალაზნის ხეობით ადიხარ ჭეშოს, ფარსმისა და გირევის გავლით. გზა ძირითადად სოფლის გრუნტის გზაა, ამიტომ ორიენტირება მარტივია.','ზომიერი აღმართები გრუნტის გზაზე. სიმაღლე ~2 000 მ-ია.','ომალომდე საზოგადოებრივი ტრანსპორტი არ დადის. თბილისიდან ქვემო ალვანამდე მარშრუტკით (~2 სთ), იქიდან 4x4 ჯიპით აბანოს უღელტეხილის გავლით (~4 სთ; 2026 წლის მონაცემით 100–120 ლარი ერთ მგზავრზე). გზა ჩვეულებრივ ივნისიდან ოქტომბრამდეა ღია და საქართველოს ერთ-ერთი ყველაზე სახიფათოა — მხოლოდ გამოცდილ ადგილობრივ მძღოლთან იარე. გირევიდან უკან ომალოში ჯიპით ან იმავე გზით.','დართლოში, ჭეშოში, ფარსმასა და გირევში საოჯახო სასტუმროებია, ჩვეულებრივ ვახშმით.','სოფლებში წყალი არის.','გირევში სასაზღვრო პუნქტია — პასპორტი თან იქონიე.','მწყემსის ძაღლები. ზოგიერთ სალოცავთან (ნიშით მონიშნულია) ქალების მისვლა ტრადიციით არ შეიძლება — პატივი ეცი.','ომალოში არის, ხეობაში — ნაწილობრივ.',seed.gear(array['BOOTS','BACKPACK_MULTI','RAIN','FLEECE','HAT_GLOVES','SUN','WATER_2','FILTER','SNACKS','FIRST_AID','OFFLINE_MAP','POLES_REQ','HEADLAMP','POWERBANK','CASH','TRASH','ID']),array['ომალოში ერთი დღე დატოვე ომალოს ციხისა და ქვემო ომალოს დასათვალიერებლად.']::text[],'ომალო',42.37092,45.63308,'გირევი',42.49793,45.48125,false,'published','https://caucasus-trekking.com/treks/omaloshatili'),
('oreti-lake','ორეთის ტბა','Oreti lake','tusheti','hard',1,2,9,28.5,1680,1680,2660,1630,'out_and_back','{6,7,8}'::smallint[],array['lakes','flowers','forest','views']::text[],'ომალოდან ტყით და დეკიანი ფერდობებით ალპურ ორეთის ტბამდე — გრძელი, მძიმე დღე, ივნისში აყვავებული დეკით.','ქვემო ომალოდან ქუმელაურთის გავლით მდინარეზე ჩადიხარ, შემდეგ ციცაბოდ ადიხარ ტყეში და დეკის ბუჩქნარში. ზემოთ მდელოები და მწყემსების ბინაა, ბოლოს — ორეთის ტბა (~2 630 მ). საუკეთესო დრო ზაფხულის დასაწყისია: სექტემბერში ტბა შეიძლება თითქმის დაშრეს.','~1 700 მ აღმართი და დაღმართი ერთ დღეში, ტყეში ციცაბო მონაკვეთებით.','ომალომდე საზოგადოებრივი ტრანსპორტი არ დადის. თბილისიდან ქვემო ალვანამდე მარშრუტკით (~2 სთ), იქიდან 4x4 ჯიპით აბანოს უღელტეხილის გავლით (~4 სთ; 2026 წლის მონაცემით 100–120 ლარი ერთ მგზავრზე). გზა ჩვეულებრივ ივნისიდან ოქტომბრამდეა ღია და საქართველოს ერთ-ერთი ყველაზე სახიფათოა — მხოლოდ გამოცდილ ადგილობრივ მძღოლთან იარე.','ომალოში საოჯახო სასტუმროები. ორ დღედ გაყოფისას — კარავი ტბასთან.','ტბასთან ნაკადულია — გაწმინდე.','არ არის საჭირო.','გრძელი დღე — გამოდი ადრე. ჯობს ჯგუფით იარო და მწყემსების ბინებთან არ შეჩერდე.','ომალოს ახლოს არის, ზემოთ — სუსტი.',seed.gear(array['BOOTS','BACKPACK_DAY','WATER_2','RAIN','FLEECE','SUN','SNACKS','FIRST_AID','OFFLINE_MAP','POLES','HEADLAMP','TRASH','POLES_REQ','FILTER']),array['ივნისის შუა რიცხვებში დეკის ყვავილობა ამ მარშრუტს განსაკუთრებულს ხდის.']::text[],'ქვემო ომალო',42.37092,45.63308,'ორეთის ტბა',42.30759,45.64039,false,'published','https://www.caucasus-trekking.com/treks/oreti')
